-- ve-pre-vegan-business-guide: plant-based language in the members' text and the survey (Sean approved 2026-11-06).
-- canon-ve-pre-vegan-meaning: a business that is not Vegan offers plant-based (Pre-Vegan) options, never "Vegan options", in our own copy.
-- Only words change; stored survey answers keep their values.
update ve_guides set content_html = '<script type="application/json" id="pb-data">{"adds": [{"id": "gym", "title": "Gym or studio", "short": "Shakes, bars and recovery drinks that work for everyone who trains with you.", "firsts": ["A pea or soy protein shake on the menu beside the whey one, made with oat or soy milk.", "Two or three plant-based protein bars at the counter.", "A recovery smoothie: banana, peanut butter, oats and a plant milk.", "Electrolyte drinks and coconut water (most are plant-based; read the label)."], "stock": ["A plant-based protein powder (pea, soy, rice or a blend) in one or two flavors.", "Oat and soy milk; soy has the most protein of the common plant milks.", "Bars that say Vegan on the label."], "watch": ["Whey, casein and milk protein are dairy. Collagen comes from animals.", "Vitamin D3 is often made from lanolin (sheep''s wool); D2 or a lichen D3 is plant-based.", "Omega-3 from fish oil comes from animals; algae oil is plant-based.", "Honey in bars and shakes."], "start": "Add one plant-based shake and one plant-based bar this month. Put them at eye level, not in a separate corner."}, {"id": "juice", "title": "Juice or smoothie bar", "short": "Most of the menu is close already. Check the bases and the toppings.", "firsts": ["Mark the juices that are already plant-based. Most fruit and vegetable juices are.", "Offer a plant milk or juice base for every smoothie that uses yogurt or milk.", "An acai or smoothie bowl with granola and nut butter, no honey."], "stock": ["Oat, almond or coconut milk and a dairy-free yogurt.", "Agave, maple or date syrup as the sweetener people can choose.", "A plant-based protein powder as an add-in."], "watch": ["Honey, yogurt, whey and milk in bases and boosts.", "Granola made with honey or butter.", "Some sherbets contain milk; sorbet usually does not."], "start": "Go through your menu and mark what is plant-based today. Then swap honey for agave on the drinks where it makes no difference to the taste."}, {"id": "cafe", "title": "Cafe or bakery", "short": "Baked goods are where butter, eggs and milk hide. Start with a few items you can make well.", "firsts": ["One plant-based muffin or cookie that sells every day.", "A plant-based sandwich or wrap with a real protein: tofu, tempeh, chickpeas or a plant-based deli slice.", "Avocado or hummus toast on bread that has no milk or egg."], "stock": ["A plant-based butter for baking and for spreading.", "A plant milk that bakes well (soy or oat).", "An egg replacer for baking, or flax and aquafaba from your own pantry."], "watch": ["Egg wash on pastries and breads, and butter brushed on top.", "Milk, whey or butter in breads and croissants.", "Glazes and sprinkles can use confectioner''s glaze (shellac); some red colors are carmine, from insects."], "start": "Bake one plant-based item side by side with your usual version and taste them. Put the one that wins on the counter with a clear label."}, {"id": "caterer", "title": "Caterer or venue", "short": "Guests ask for it now. Have a plant-based option ready before the event, not on the day.", "firsts": ["One plant-based main on every standard menu, not a plate of side dishes.", "A plant-based option on the dessert table.", "Mark plant-based items on place cards and buffet labels."], "stock": ["A plant-based protein you trust at volume (ready-made, or from Buy or make).", "Plant-based butter and stock, so sides can be made plant-based by default.", "A plant milk and creamer for the coffee service."], "watch": ["Butter, cream and chicken stock in sides, sauces and rice.", "Shared fryers and grills, and serving spoons moved between dishes.", "Worcestershire (often anchovies), fish sauce, and lard in some tortillas and beans."], "start": "Write one plant-based main and one plant-based dessert into your standard packages, cost them, and serve them at your next tasting."}]}</script>' where slug = 'pre-vegan-business-guide';
update ve_survey_questions set prompt = 'What plant-based options do you serve today?',
  options = '[{"v":"none","label":"Nothing yet"},{"v":"one","label":"One or two items"},{"v":"few","label":"A few items"},{"v":"section","label":"A full plant-based section"}]'::jsonb
  where survey_slug = 'pre-vegan-business-guide' and id = 'pb_now';
update ve_survey_questions set prompt = 'What is your biggest worry about adding plant-based options?'
  where survey_slug = 'pre-vegan-business-guide' and id = 'pb_worry';
